@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply font-sans antialiased bg-background text-foreground;
  }
}

/**
 * Using the elevate system.
 * Automatic contrast adjustment.
 *
 * <element className="hover-elevate" />
 * <element className="active-elevate-2" />
 *
 * // Using the tailwind utility when a data attribute is "on"
 * <element className="toggle-elevate data-[state=on]:toggle-elevated" />
 * // Or manually controlling the toggle state
 * <element className="toggle-elevate toggle-elevated" />
 *
 * Elevation systems have to handle many states.
 * - not-hovered, vs. hovered vs. active  (three mutually exclusive states)
 * - toggled or not
 * - focused or not (this is not handled with these utilities)
 *
 * Even without handling focused or not, this is six possible combinations that
 * need to be distinguished from eachother visually.
 */
@layer utilities {

  /* Hide ugly search cancel button in Chrome until we can style it properly */
  input[type="search"]::-webkit-search-cancel-button {
    @apply hidden;
  }

  /* Placeholder styling for contentEditable div */
  [contenteditable][data-placeholder]:empty::before {
    content: attr(data-placeholder);
    color: hsl(var(--muted-foreground));
    pointer-events: none;
  }

  /* .no-default-hover-elevate/no-default-active-elevate is an escape hatch so consumers of
   * buttons/badges can remove the automatic brightness adjustment on interactions
   * and program their own. */
  .no-default-hover-elevate {}

  .no-default-active-elevate {}


  /**
   * Toggleable backgrounds go behind the content. Hoverable/active goes on top.
   * This way they can stack/compound. Both will overlap the parent's borders!
   * So borders will be automatically adjusted both on toggle, and hover/active,
   * and they will be compounded.
   */
  .toggle-elevate::before,
  .toggle-elevate-2::before {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    /*border-radius: inherit;   match rounded corners */
    border-radius: inherit;
    z-index: -1;
    /* sits behind content but above backdrop */
  }

  .toggle-elevate.toggle-elevated::before {
    background-color: var(--elevate-2);
  }

  /* If there's a 1px border, adjust the inset so that it covers that parent's border */
  .border.toggle-elevate::before {
    inset: -1px;
  }

  /* Does not work on elements with overflow:hidden! */
  .hover-elevate:not(.no-default-hover-elevate),
  .active-elevate:not(.no-default-active-elevate),
  .hover-elevate-2:not(.no-default-hover-elevate),
  .active-elevate-2:not(.no-default-active-elevate) {
    position: relative;
    z-index: 0;
  }

  .hover-elevate:not(.no-default-hover-elevate)::after,
  .active-elevate:not(.no-default-active-elevate)::after,
  .hover-elevate-2:not(.no-default-hover-elevate)::after,
  .active-elevate-2:not(.no-default-active-elevate)::after {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    /*border-radius: inherit;   match rounded corners */
    border-radius: inherit;
    z-index: 999;
    /* sits in front of content */
  }

  .hover-elevate:hover:not(.no-default-hover-elevate)::after,
  .active-elevate:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-1);
  }

  .hover-elevate-2:hover:not(.no-default-hover-elevate)::after,
  .active-elevate-2:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-2);
  }

  /* If there's a 1px border, adjust the inset so that it covers that parent's border */
  .border.hover-elevate:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate-2:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate-2:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate:not(.no-hover-interaction-elevate)::after {
    inset: -1px;
  }

  /* ====================================
   * RTL Support & Arabic Typography
   * ==================================== */

  /* Better Arabic font rendering */
  [dir="rtl"] {
    font-family: var(--font-arabic);
  }

  [dir="ltr"] {
    font-family: var(--font-english);
  }

  /* RTL-aware spacing utilities */
  .ms-auto {
    margin-inline-start: auto;
  }

  .me-auto {
    margin-inline-end: auto;
  }

  .ps-4 {
    padding-inline-start: 1rem;
  }

  .pe-4 {
    padding-inline-end: 1rem;
  }

  /* Better text rendering for Arabic */
  [lang="ar"], [dir="rtl"] {
    text-align: start;
    letter-spacing: normal;
  }

  /* Fix icon rotation in RTL */
  [dir="rtl"] .rtl-flip {
    transform: scaleX(-1);
  }

  /* ====================================
   * Accessibility Improvements
   * ==================================== */

  /* Skip to content link */
  .skip-to-content {
    position: absolute;
    top: -100px;
    left: 0;
    background: hsl(var(--primary));
    color: hsl(var(--primary-foreground));
    padding: 0.5rem 1rem;
    text-decoration: none;
    border-radius: 0 0 0.375rem 0;
    z-index: 9999;
    font-weight: 600;
    transition: top 0.2s ease-in-out;
  }

  .skip-to-content:focus {
    top: 0;
  }

  /* Enhanced focus indicators (WCAG AA compliant) */
  *:focus-visible {
    outline: 2px solid hsl(var(--ring));
    outline-offset: 2px;
    border-radius: 0.25rem;
  }

  /* Remove default focus outline but keep for keyboard navigation */
  *:focus:not(:focus-visible) {
    outline: none;
  }

  /* High contrast focus for interactive elements */
  button:focus-visible,
  a:focus-visible,
  [role="button"]:focus-visible,
  input:focus-visible,
  select:focus-visible,
  textarea:focus-visible {
    outline: 3px solid hsl(var(--ring));
    outline-offset: 2px;
  }

  /* Screen reader only content */
  .sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
  }

  .sr-only-focusable:focus {
    position: static;
    width: auto;
    height: auto;
    padding: initial;
    margin: initial;
    overflow: visible;
    clip: auto;
    white-space: normal;
  }

  /* ====================================
   * Premium $5M Look - Glow Effects
   * ==================================== */

  /* Gold text with shimmer effect */
  .gold-text {
    color: hsl(var(--accent));
    text-shadow: 0 0 10px rgba(255, 215, 0, 0.5);
  }

  /* Sky blue glow */
  .neon-glow {
    box-shadow: 0 0 20px rgba(135, 206, 250, 0.6),
                0 0 40px rgba(135, 206, 250, 0.4),
                0 0 60px rgba(135, 206, 250, 0.3);
  }

  /* Gold glow effect */
  .gold-glow {
    box-shadow: 0 0 20px rgba(255, 215, 0, 0.6),
                0 0 40px rgba(255, 215, 0, 0.4),
                0 0 60px rgba(255, 215, 0, 0.2);
  }

  /* Premium border with glow */
  .premium-border {
    border: 1px solid hsl(var(--primary));
    box-shadow: 0 0 15px rgba(135, 206, 250, 0.4);
  }

  /* Gold accent border with glow */
  .gold-border {
    border: 1px solid hsl(var(--accent));
    box-shadow: 0 0 15px rgba(255, 215, 0, 0.4);
  }

  /* ====================================
   * Animations & Transitions
   * ==================================== */

  /* Respect reduced motion preferences */
  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
  }

  /* Smooth page transitions */
  @keyframes fadeIn {
    from {
      opacity: 0;
      transform: translateY(10px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes fadeOut {
    from {
      opacity: 1;
      transform: translateY(0);
    }
    to {
      opacity: 0;
      transform: translateY(-10px);
    }
  }

  @keyframes slideInFromRight {
    from {
      opacity: 0;
      transform: translateX(20px);
    }
    to {
      opacity: 1;
      transform: translateX(0);
    }
  }

  @keyframes slideInFromLeft {
    from {
      opacity: 0;
      transform: translateX(-20px);
    }
    to {
      opacity: 1;
      transform: translateX(0);
    }
  }

  @keyframes scaleIn {
    from {
      opacity: 0;
      transform: scale(0.95);
    }
    to {
      opacity: 1;
      transform: scale(1);
    }
  }

  @keyframes shimmer {
    0% {
      background-position: -1000px 0;
    }
    100% {
      background-position: 1000px 0;
    }
  }

  @keyframes goldShimmer {
    0% {
      text-shadow: 0 0 10px rgba(255, 215, 0, 0.5),
                   0 0 20px rgba(255, 215, 0, 0.3);
    }
    50% {
      text-shadow: 0 0 20px rgba(255, 215, 0, 0.8),
                   0 0 40px rgba(255, 215, 0, 0.5),
                   0 0 60px rgba(255, 215, 0, 0.3);
    }
    100% {
      text-shadow: 0 0 10px rgba(255, 215, 0, 0.5),
                   0 0 20px rgba(255, 215, 0, 0.3);
    }
  }

  @keyframes neonPulse {
    0%, 100% {
      box-shadow: 0 0 20px rgba(135, 206, 250, 0.6),
                  0 0 40px rgba(135, 206, 250, 0.4);
    }
    50% {
      box-shadow: 0 0 30px rgba(135, 206, 250, 0.9),
                  0 0 60px rgba(135, 206, 250, 0.6),
                  0 0 90px rgba(135, 206, 250, 0.4);
    }
  }

  .animate-in {
    animation: fadeIn 0.4s ease-out;
  }

  .animate-in-fast {
    animation: fadeIn 0.2s ease-out;
  }

  .animate-slide-in-right {
    animation: slideInFromRight 0.3s ease-out;
  }

  .animate-slide-in-left {
    animation: slideInFromLeft 0.3s ease-out;
  }

  .animate-scale-in {
    animation: scaleIn 0.3s ease-out;
  }

  .animate-gold-shimmer {
    animation: goldShimmer 3s ease-in-out infinite;
  }

  .animate-neon-pulse {
    animation: neonPulse 2s ease-in-out infinite;
  }

  /* Skeleton loading animation */
  .skeleton-shimmer {
    background: linear-gradient(
      90deg,
      hsl(var(--muted)) 0%,
      hsl(var(--muted) / 0.7) 50%,
      hsl(var(--muted)) 100%
    );
    background-size: 1000px 100%;
    animation: shimmer 2s infinite linear;
  }

  /* Smooth transitions */
  .transition-smooth {
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .transition-fast {
    transition: all 0.15s ease-in-out;
  }

  /* Micro-interactions */
  .button-press {
    transition: transform 0.1s ease-in-out;
  }

  .button-press:active {
    transform: scale(0.97);
  }

  /* Pulse animation for loading indicators */
  @keyframes pulse {
    0%, 100% {
      opacity: 1;
    }
    50% {
      opacity: 0.5;
    }
  }

  .animate-pulse-slow {
    animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
  }

  /* ====================================
   * Toast Notification Enhancements
   * ==================================== */

  /* Toast variants with icons */
  .toast-success {
    border-left: 4px solid hsl(var(--chart-3));
    background: hsl(var(--card));
  }

  [dir="rtl"] .toast-success {
    border-left: none;
    border-right: 4px solid hsl(var(--chart-3));
  }

  .toast-error {
    border-left: 4px solid hsl(var(--destructive));
    background: hsl(var(--card));
  }

  [dir="rtl"] .toast-error {
    border-left: none;
    border-right: 4px solid hsl(var(--destructive));
  }

  .toast-warning {
    border-left: 4px solid hsl(var(--accent));
    background: hsl(var(--card));
  }

  [dir="rtl"] .toast-warning {
    border-left: none;
    border-right: 4px solid hsl(var(--accent));
  }

  .toast-info {
    border-left: 4px solid hsl(var(--primary));
    background: hsl(var(--card));
  }

  [dir="rtl"] .toast-info {
    border-left: none;
    border-right: 4px solid hsl(var(--primary));
  }

  /* ====================================
   * Responsive Design Utilities
   * ==================================== */

  /* Touch-friendly tap targets (minimum 44px) */
  .tap-target {
    min-height: 44px;
    min-width: 44px;
  }

  /* Mobile-optimized scrolling */
  .mobile-scroll {
    -webkit-overflow-scrolling: touch;
    overflow-x: auto;
    scroll-behavior: smooth;
  }

  /* Hide scrollbar but keep functionality */
  .scrollbar-hide {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }

  .scrollbar-hide::-webkit-scrollbar {
    display: none;
  }

  /* ====================================
   * Premium Visual Details
   * ==================================== */

  /* Subtle gradient overlays */
  .gradient-overlay {
    position: relative;
  }

  .gradient-overlay::before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
      135deg,
      transparent 0%,
      hsl(var(--primary) / 0.05) 100%
    );
    pointer-events: none;
  }

  /* Glass morphism effect with premium look */
  .glass {
    background: rgba(0, 0, 0, 0.7);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(135, 206, 250, 0.15);
  }

  /* Elevated card with sky blue glow */
  .card-elevated {
    box-shadow: 
      0 0 20px rgba(135, 206, 250, 0.2),
      0 4px 6px -1px rgba(0, 0, 0, 0.5);
    transition: box-shadow 0.3s ease;
  }

  .card-elevated:hover {
    box-shadow: 
      0 0 30px rgba(135, 206, 250, 0.4),
      0 8px 12px -2px rgba(0, 0, 0, 0.6);
  }

  /* ====================================
   * Loading States
   * ==================================== */

  /* Spinner animation */
  @keyframes spin {
    to {
      transform: rotate(360deg);
    }
  }

  .animate-spin-slow {
    animation: spin 2s linear infinite;
  }

  /* Button loading state */
  .button-loading {
    position: relative;
    pointer-events: none;
    opacity: 0.7;
  }

  .button-loading::after {
    content: "";
    position: absolute;
    inset: 0;
    background: inherit;
    border-radius: inherit;
  }

  /* ====================================
   * Form & Input Enhancements
   * ==================================== */

  /* Floating labels */
  .floating-input:focus + label,
  .floating-input:not(:placeholder-shown) + label {
    transform: translateY(-1.5rem) scale(0.875);
    color: hsl(var(--primary));
  }

  /* Invalid input styling */
  input:invalid:not(:placeholder-shown),
  textarea:invalid:not(:placeholder-shown) {
    border-color: hsl(var(--destructive));
  }

  /* Valid input styling */
  input:valid:not(:placeholder-shown),
  textarea:valid:not(:placeholder-shown) {
    border-color: hsl(var(--chart-3));
  }
}

