import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Pagination, PaginationContent, PaginationEllipsis, PaginationItem, PaginationLink, PaginationNext, PaginationPrevious } from "@/components/ui/pagination";
import { DollarSign, CheckCircle2, Clock, AlertCircle } from "lucide-react";
import type { Payment } from "@shared/schema";

interface PaginatedResponse<T> {
  data: T[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

export default function AdminPayments() {
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);

  const { data, isLoading } = useQuery<PaginatedResponse<Payment>>({
    queryKey: ["/api/admin/payments", page, pageSize],
    queryFn: async () => {
      const params = new URLSearchParams({
        page: page.toString(),
        limit: pageSize.toString(),
      });

      const response = await fetch(`/api/admin/payments?${params}`);
      if (!response.ok) throw new Error('Failed to fetch payments');
      return response.json();
    },
  });

  const payments = data?.data || [];
  const pagination = data?.pagination;

  const handlePageChange = (newPage: number) => {
    setPage(newPage);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handlePageSizeChange = (newSize: string) => {
    setPageSize(parseInt(newSize));
    setPage(1);
  };

  const startItem = pagination ? (pagination.page - 1) * pagination.limit + 1 : 0;
  const endItem = pagination ? Math.min(pagination.page * pagination.limit, pagination.total) : 0;

  const totalRevenue = payments
    .filter(p => p.paymentStatus === 'completed')
    .reduce((sum, p) => sum + Number(p.amount), 0);

  const completedCount = payments.filter(p => p.paymentStatus === 'completed').length;
  const pendingCount = payments.filter(p => p.paymentStatus === 'pending').length;

  return (
    <div className="p-6 md:p-8 space-y-6">
      <div>
        <h1 className="text-3xl md:text-4xl font-bold text-foreground mb-2">المدفوعات</h1>
        <p className="text-muted-foreground text-lg">إدارة ومراقبة المعاملات المالية</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <Card className="hover-elevate">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2 gap-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">
              إجمالي الإيرادات (الصفحة الحالية)
            </CardTitle>
            <DollarSign className="h-5 w-5 text-chart-2" />
          </CardHeader>
          <CardContent>
            <div className="text-3xl font-bold text-foreground" data-testid="text-total-revenue">
              {totalRevenue.toLocaleString()} جنيه
            </div>
          </CardContent>
        </Card>

        <Card className="hover-elevate">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2 gap-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">
              مدفوعات مكتملة (الصفحة الحالية)
            </CardTitle>
            <CheckCircle2 className="h-5 w-5 text-chart-3" />
          </CardHeader>
          <CardContent>
            <div className="text-3xl font-bold text-foreground" data-testid="text-completed-count">
              {completedCount}
            </div>
          </CardContent>
        </Card>

        <Card className="hover-elevate">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2 gap-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">
              مدفوعات معلقة (الصفحة الحالية)
            </CardTitle>
            <Clock className="h-5 w-5 text-accent" />
          </CardHeader>
          <CardContent>
            <div className="text-3xl font-bold text-foreground" data-testid="text-pending-count">
              {pendingCount}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Page Size Selector */}
      <div className="flex items-center justify-between">
        {pagination && pagination.total > 0 && (
          <p className="text-sm text-muted-foreground" data-testid="text-pagination-info">
            Showing {startItem}-{endItem} of {pagination.total} payments
          </p>
        )}
        <Select value={pageSize.toString()} onValueChange={handlePageSizeChange}>
          <SelectTrigger className="w-[150px]" data-testid="select-page-size">
            <SelectValue placeholder="Page size" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="10">10 per page</SelectItem>
            <SelectItem value="20">20 per page</SelectItem>
            <SelectItem value="50">50 per page</SelectItem>
            <SelectItem value="100">100 per page</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>سجل المدفوعات</CardTitle>
          <CardDescription>جميع المعاملات المالية</CardDescription>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <div className="space-y-4">
              {[...Array(5)].map((_, i) => (
                <Skeleton key={i} className="h-20 w-full" />
              ))}
            </div>
          ) : payments.length === 0 ? (
            <div className="text-center py-12">
              <DollarSign className="h-12 w-12 mx-auto text-muted-foreground mb-3" />
              <p className="text-muted-foreground">لا توجد مدفوعات بعد</p>
            </div>
          ) : (
            <>
              <div className="space-y-3">
                {payments.map((payment, index) => (
                <div key={payment.id} className="flex items-center justify-between p-4 rounded-lg border border-border hover-elevate" data-testid={`row-payment-${index}`}>
                  <div className="flex items-center gap-4">
                    <div className={`w-12 h-12 rounded-full flex items-center justify-center ${
                      payment.paymentStatus === 'completed' 
                        ? 'bg-chart-3/10' 
                        : payment.paymentStatus === 'pending'
                        ? 'bg-accent/10'
                        : 'bg-destructive/10'
                    }`}>
                      {payment.paymentStatus === 'completed' ? (
                        <CheckCircle2 className="w-6 h-6 text-chart-3" />
                      ) : payment.paymentStatus === 'pending' ? (
                        <Clock className="w-6 h-6 text-accent" />
                      ) : (
                        <AlertCircle className="w-6 h-6 text-destructive" />
                      )}
                    </div>
                    <div>
                      <p className="font-bold text-foreground" data-testid={`text-amount-${index}`}>
                        {Number(payment.amount).toLocaleString()} {payment.currency}
                      </p>
                      <p className="text-sm text-muted-foreground" data-testid={`text-method-${index}`}>
                        {payment.paymentMethod === 'vodafone_cash' ? 'فودافون كاش' : payment.paymentMethod === 'cash' ? 'نقدي' : 'تحويل بنكي'}
                      </p>
                      <p className="text-xs text-muted-foreground" data-testid={`text-date-${index}`}>
                        {new Date(payment.createdAt).toLocaleDateString('ar-EG')}
                      </p>
                    </div>
                  </div>
                  <Badge variant={
                    payment.paymentStatus === 'completed' ? 'default' : 
                    payment.paymentStatus === 'pending' ? 'secondary' : 
                    'destructive'
                  } data-testid={`badge-status-${index}`}>
                    {payment.paymentStatus === 'completed' ? 'مكتمل' : 
                     payment.paymentStatus === 'pending' ? 'معلق' : 
                     'فشل'}
                  </Badge>
                </div>
                ))}
              </div>

              {/* Pagination */}
              {pagination && pagination.totalPages > 1 && (
                <div className="mt-6 flex flex-col sm:flex-row items-center justify-between gap-4">
                  <div className="text-sm text-muted-foreground">
                    Page {pagination.page} of {pagination.totalPages}
                  </div>
                  <Pagination>
                    <PaginationContent>
                      <PaginationItem>
                        <PaginationPrevious
                          onClick={() => handlePageChange(Math.max(1, pagination.page - 1))}
                          className={pagination.page === 1 ? 'pointer-events-none opacity-50' : 'cursor-pointer'}
                          data-testid="button-prev-page"
                        />
                      </PaginationItem>

                      {Array.from({ length: Math.min(5, pagination.totalPages) }, (_, i) => {
                        let pageNumber;
                        if (pagination.totalPages <= 5) {
                          pageNumber = i + 1;
                        } else if (pagination.page <= 3) {
                          pageNumber = i + 1;
                        } else if (pagination.page >= pagination.totalPages - 2) {
                          pageNumber = pagination.totalPages - 4 + i;
                        } else {
                          pageNumber = pagination.page - 2 + i;
                        }

                        return (
                          <PaginationItem key={pageNumber}>
                            <PaginationLink
                              onClick={() => handlePageChange(pageNumber)}
                              isActive={pagination.page === pageNumber}
                              className="cursor-pointer"
                              data-testid={`button-page-${pageNumber}`}
                            >
                              {pageNumber}
                            </PaginationLink>
                          </PaginationItem>
                        );
                      })}

                      {pagination.totalPages > 5 && pagination.page < pagination.totalPages - 2 && (
                        <PaginationItem>
                          <PaginationEllipsis />
                        </PaginationItem>
                      )}

                      <PaginationItem>
                        <PaginationNext
                          onClick={() => handlePageChange(Math.min(pagination.totalPages, pagination.page + 1))}
                          className={pagination.page === pagination.totalPages ? 'pointer-events-none opacity-50' : 'cursor-pointer'}
                          data-testid="button-next-page"
                        />
                      </PaginationItem>
                    </PaginationContent>
                  </Pagination>
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/client-profile.tsx.content:
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useState } from "react";
import { User, Save } from "lucide-react";
import type { BuyerProfile } from "@shared/schema";

export default function ClientProfile() {
  const { toast } = useToast();
  const { data: profile } = useQuery<BuyerProfile>({
    queryKey: ["/api/client/profile"],
  });

  const [budget, setBudget] = useState(profile?.budget?.toString() || "");
  const [riskTolerance, setRiskTolerance] = useState(profile?.riskTolerance || "moderate");
  const [investmentGoal, setInvestmentGoal] = useState(profile?.investmentGoal || "");

  const updateProfileMutation = useMutation({
    mutationFn: async (data: any) => {
      await apiRequest("PUT", "/api/client/profile", data);
    },
    onSuccess: () => {
      toast({
        title: "نجاح",
        description: "تم تحديث الملف الشخصي بنجاح",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/client/profile"] });
    },
    onError: () => {
      toast({
        title: "خطأ",
        description: "فشل في تحديث الملف الشخصي",
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    updateProfileMutation.mutate({
      budget: budget ? parseFloat(budget) : undefined,
      riskTolerance,
      investmentGoal,
    });
  };

  return (
    <div className="p-6 md:p-8 space-y-8">
      <div>
        <h1 className="text-3xl md:text-4xl font-bold text-foreground mb-2">الملف الشخصي</h1>
        <p className="text-muted-foreground text-lg">إدارة معلوماتك وتفضيلاتك</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <User className="w-5 h-5" />
              تفضيلات الاستثمار
            </CardTitle>
            <CardDescription>أخبرنا عن أهدافك الاستثمارية</CardDescription>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-6">
              <div>
                <Label htmlFor="budget" data-testid="label-budget">الميزانية (جنيه مصري)</Label>
                <Input
                  id="budget"
                  type="number"
                  value={budget}
                  onChange={(e) => setBudget(e.target.value)}
                  placeholder="مثال: 1000000"
                  className="mt-2"
                  data-testid="input-budget"
                />
              </div>

              <div>
                <Label htmlFor="risk" data-testid="label-risk">تحمل المخاطر</Label>
                <Select value={riskTolerance} onValueChange={setRiskTolerance}>
                  <SelectTrigger className="mt-2" data-testid="select-risk-trigger">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="conservative" data-testid="select-risk-conservative">محافظ</SelectItem>
                    <SelectItem value="moderate" data-testid="select-risk-moderate">متوسط</SelectItem>
                    <SelectItem value="aggressive" data-testid="select-risk-aggressive">مخاطر عالية</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label htmlFor="goal" data-testid="label-goal">الهدف الاستثماري</Label>
                <Textarea
                  id="goal"
                  value={investmentGoal}
                  onChange={(e) => setInvestmentGoal(e.target.value)}
                  placeholder="مثال: استثمار طويل الأجل للإيجار"
                  className="mt-2 min-h-24"
                  data-testid="textarea-goal"
                />
              </div>

              <Button
                type="submit"
                className="w-full bg-accent hover:bg-accent/90"
                disabled={updateProfileMutation.isPending}
                data-testid="button-save-profile"
              >
                <Save className="w-4 h-4 me-2" />
                {updateProfileMutation.isPending ? 'جاري الحفظ...' : 'حفظ التغييرات'}
              </Button>
            </form>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>اكتمال الملف</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-center space-y-4">
              <div className="text-5xl font-bold text-accent" data-testid="text-completion">
                {profile?.profileCompletion || 0}%
              </div>
              <p className="text-sm text-muted-foreground">
                أكمل ملفك الشخصي للحصول على توصيات أفضل
              </p>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

client/src/components/ui/badge.tsx.content:
import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const badgeVariants = cva(
  // Whitespace-nowrap: Badges should never wrap.
  "whitespace-nowrap inline-flex items-center rounded-md border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2" +
  " hover-elevate " ,
  {
    variants: {
      variant: {
        default:
          "border-transparent bg-primary text-primary-foreground shadow-xs",
        secondary: "border-transparent bg-secondary text-secondary-foreground",
        destructive:
          "border-transparent bg-destructive text-destructive-foreground shadow-xs",

        outline: " border [border-color:var(--badge-outline)] shadow-xs",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
)

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return (
    <div className={cn(badgeVariants({ variant }), className)} {...props} />
  );
}

export { Badge, badgeVariants }

client/src/components/app-sidebar.tsx.content:
import { Link, useLocation } from "wouter";
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarHeader,
  SidebarFooter,
} from "@/components/ui/sidebar";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { useI18n } from "@/lib/i18n";
import { useAuth } from "@/hooks/useAuth";
import {
  LayoutDashboard,
  Building2,
  MessageSquare,
  TrendingUp,
  Users,
  FileText,
  Settings,
  LogOut,
  Upload,
  BarChart3,
  Wallet,
  Gift,
  Calendar,
} from "lucide-react";

export function AppSidebar() {
  const [location] = useLocation();
  const { t } = useI18n();
  const { user } = useAuth();

  const adminMenuItems = [
    {
      title: t("nav.dashboard"),
      url: "/admin",
      icon: LayoutDashboard,
    },
    {
      title: "حجوزات الاستشارات",
      url: "/admin/consultations",
      icon: Calendar,
    },
    {
      title: "تحميل بيانات السوق",
      url: "/admin/market-upload",
      icon: Upload,
    },
    {
      title: "تحليلات سلوكية",
      url: "/admin/analytics",
      icon: BarChart3,
    },
    {
      title: t("nav.developers"),
      url: "/admin/developers",
      icon: Building2,
    },
    {
      title: "المدفوعات",
      url: "/admin/payments",
      icon: Wallet,
    },
  ];

  const clientMenuItems = [
    {
      title: t("nav.dashboard"),
      url: "/client",
      icon: LayoutDashboard,
    },
    {
      title: "حجز استشارة",
      url: "/client/book-consultation",
      icon: Calendar,
    },
    {
      title: t("nav.consultations"),
      url: "/client/consultations",
      icon: MessageSquare,
    },
    {
      title: t("nav.properties"),
      url: "/client/properties",
      icon: Building2,
    },
    {
      title: t("nav.market"),
      url: "/client/market",
      icon: TrendingUp,
    },
    {
      title: "الملف الشخصي",
      url: "/client/profile",
      icon: Users,
    },
    {
      title: "الإحالات",
      url: "/client/referrals",
      icon: Gift,
    },
  ];

  const developerMenuItems = [
    {
      title: t("nav.dashboard"),
      url: "/developer",
      icon: LayoutDashboard,
    },
    {
      title: "عقاراتي",
      url: "/developer/properties",
      icon: Building2,
    },
    {
      title: "العملاء المحتملون",
      url: "/developer/leads",
      icon: Users,
    },
    {
      title: "نقاط الثقة",
      url: "/developer/trust-score",
      icon: BarChart3,
    },
  ];

  const menuItems = user?.role === 'admin' 
    ? adminMenuItems 
    : user?.role === 'developer' 
    ? developerMenuItems 
    : clientMenuItems;

  const getRoleLabel = () => {
    if (user?.role === 'admin') return 'مدير';
    if (user?.role === 'developer') return 'مطور';
    return 'عميل';
  };

  const getUserInitials = () => {
    if (user?.firstName && user?.lastName) {
      return `${user.firstName[0]}${user.lastName[0]}`;
    }
    return user?.email?.[0]?.toUpperCase() || 'U';
  };

  return (
    <Sidebar>
      <SidebarHeader className="p-6 border-b border-sidebar-border">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-primary flex items-center justify-center">
            <Building2 className="w-6 h-6 text-primary-foreground" />
          </div>
          <div>
            <h2 className="font-bold text-lg text-sidebar-foreground">منصة الاستشارات</h2>
            <p className="text-xs text-muted-foreground">Real Estate Platform</p>
          </div>
        </div>
      </SidebarHeader>

      <SidebarContent>
        <SidebarGroup>
          <SidebarGroupLabel className="text-muted-foreground">القائمة الرئيسية</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {menuItems.map((item) => (
                <SidebarMenuItem key={item.url}>
                  <SidebarMenuButton asChild isActive={location === item.url}>
                    <Link href={item.url} data-testid={`link-${item.url.replace(/\//g, '-')}`}>
                      <item.icon className="w-5 h-5" />
                      <span>{item.title}</span>
                    </Link>
                  </SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>

      <SidebarFooter className="p-4 border-t border-sidebar-border">
        <div className="flex items-center gap-3 mb-3 p-3 rounded-lg bg-sidebar-accent/50">
          <Avatar className="w-10 h-10">
            <AvatarImage src={user?.profileImageUrl || ''} />
            <AvatarFallback className="bg-primary text-primary-foreground font-medium">
              {getUserInitials()}
            </AvatarFallback>
          </Avatar>
          <div className="flex-1 min-w-0">
            <p className="font-medium text-sm text-sidebar-foreground truncate">
              {user?.firstName || user?.email}
            </p>
            <Badge variant="secondary" className="text-xs">
              {getRoleLabel()}
            </Badge>
          </div>
        </div>
        <Button 
          variant="outline" 
          className="w-full justify-start gap-2"
          onClick={() => window.location.href = '/api/logout'}
          data-testid="button-logout"
