import { cn } from "@/lib/utils";

interface ResponsiveTableWrapperProps {
  children: React.ReactNode;
  className?: string;
}

/**
 * Responsive table wrapper that:
 * - Enables horizontal scrolling on mobile
 * - Maintains touch-friendly scrolling
