      <div className="md:hidden text-xs text-muted-foreground mb-2 flex items-center gap-2" aria-live="polite">
        <svg 
          className="h-4 w-4" 
          fill="none" 
          stroke="currentColor" 
          viewBox="0 0 24 24"
