                </Button>
              )}
              {step === 8 && (
                <Button
                  type="button"
                  onClick={handleFinalSubmit}
                  className="flex-1"
                  disabled={createBookingMutation.isPending}
                  data-testid="button-confirm-booking"
                >
                  {createBookingMutation.isPending ? "جاري الحجز..." : "تأكيد الحجز"}
                </Button>
              )}
            </div>
          </form>
        </Form>
      </div>
    </div>
  );
}

